-- Real authenticated RLS and original-command integration; all fixtures roll back.
begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',('d0310700-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','trip-editor-'||n||'@example.test','',now(),'{"provider":"email","providers":["email"]}','{"display_name":"Editor QA"}',now(),now()from generate_series(1,4)n;
create temp table te(k text primary key,v uuid);grant all on te to authenticated;
insert into te select 'u'||n,p.id from generate_series(1,4)n join public.participants p on p.auth_user_id=('d0310700-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
create function pg_temp.id(key text)returns uuid language sql as $$select v from te where k=$1$$;
create function pg_temp.claim(n int)returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub','d0310700-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','is_anonymous',false)::text,true);end$$;
create function pg_temp.payload(s text,ids uuid[],paid bigint[],shares bigint[],amount bigint,note text default 'Editor QA')returns jsonb language sql as $$select jsonb_build_object('expense_scope',s,'target_space_id',case when s='space'then pg_temp.id('trip')else null end,'participant_ids',ids,'contribution_amounts',paid,'share_amounts',shares,'total_minor',amount,'currency_code','MYR','description',note,'category','Food','occurred_on','2026-10-31')$$;
set local role authenticated;select pg_temp.claim(1);
insert into te values('trip',public.create_space('trip','Editor privacy Trip',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role)values(pg_temp.id('trip'),pg_temp.id('u2'),'full_access'),(pg_temp.id('trip'),pg_temp.id('u3'),'full_access');
set local role authenticated;select pg_temp.claim(2);
insert into te values('private-a',(public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('trip'),pg_temp.payload('personal',array[pg_temp.id('u2')],array[10000::bigint],array[10000::bigint],10000),array[pg_temp.id('u2')])->>'expense_id')::uuid);
select is((get_trip_expense_editor(pg_temp.id('private-a'))->>'audience'),'private','self-only Trip expense is owner-private');
select is((select scope from expenses where id=pg_temp.id('private-a')),'personal','original personal canonical model');
select is((select trip_id from personal_expense_affiliations where expense_id=pg_temp.id('private-a')),pg_temp.id('trip'),'stable association, not a title match');
insert into te values('shared',(public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('trip'),pg_temp.payload('space',array[pg_temp.id('u2'),pg_temp.id('u3')],array[10000::bigint,0],array[5000::bigint,5000],10000),array[pg_temp.id('u2'),pg_temp.id('u3')])->>'expense_id')::uuid);
select pg_temp.claim(3);
insert into te values('private-b',(public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('trip'),pg_temp.payload('personal',array[pg_temp.id('u3')],array[20000::bigint],array[20000::bigint],20000),array[pg_temp.id('u3')])->>'expense_id')::uuid);
select is((select count(*)from expenses),2::bigint,'B sees own private and Shared, not A private');
select throws_ok($$select get_trip_expense_editor(pg_temp.id('private-a'))$$,'P0001','expense_not_visible','B cannot request A private by UUID');
select is((select count(*)from expense_editor_settings),2::bigint,'settings inherit parent visibility');
select is((select count(*)from personal_expense_affiliations),1::bigint,'private association does not leak other owners');
select is((select sum(s.amount_minor)from expense_shares s join expense_participations p on p.id=s.expense_participation_id join expenses e on e.id=s.expense_id where p.participant_id=pg_temp.id('u3')and e.status='active'),25000::numeric,'B personal consumption 200 + 50');
select pg_temp.claim(2);
select is((select sum(s.amount_minor)from expense_shares s join expense_participations p on p.id=s.expense_participation_id join expenses e on e.id=s.expense_id where p.participant_id=pg_temp.id('u2')and e.status='active'),15000::numeric,'A personal consumption 100 + 50');
select is((select sum(total_minor)from expenses where scope='space'),10000::numeric,'Shared total never includes private amounts');
select pg_temp.claim(1);
select is((select count(*)from expenses),1::bigint,'Trip owner sees only Shared');
select is((select count(*)from personal_expense_affiliations),0::bigint,'Trip owner cannot read private affiliations');
select is((select count(*)from expense_editor_settings),1::bigint,'owner cannot read private selections or item notes');
select throws_ok($$select get_trip_expense_editor(pg_temp.id('private-a'))$$,'P0001','expense_not_visible','Trip owner cannot bypass private UUID');
select pg_temp.claim(4);
select is((select count(*)from expenses),0::bigint,'nonmember sees no bills');
select is((select count(*)from expense_editor_settings),0::bigint,'nonmember sees no item metadata');
select throws_ok($$select get_trip_expense_editor(pg_temp.id('shared'))$$,'P0001','expense_not_visible','nonmember cannot open editor by UUID');
select pg_temp.claim(2);
insert into te values('save-command',gen_random_uuid());
select lives_ok($$select save_trip_expense_editor(pg_temp.id('save-command'),pg_temp.id('private-a'),1,pg_temp.id('trip'),'private',false,pg_temp.payload('personal',array[pg_temp.id('u2')],array[10000::bigint],array[10000::bigint],10000,'Updated private note'),array[pg_temp.id('u2')])$$,'one atomic metadata save');
select is((select version from expenses where id=pg_temp.id('private-a')),2,'metadata expected version advanced');
select lives_ok($$select save_trip_expense_editor(pg_temp.id('save-command'),pg_temp.id('private-a'),1,pg_temp.id('trip'),'private',false,pg_temp.payload('personal',array[pg_temp.id('u2')],array[10000::bigint],array[10000::bigint],10000,'Updated private note'),array[pg_temp.id('u2')])$$,'same request reconciles after expected version advanced');
select is((reconcile_personal_money_operation(pg_temp.id('save-command'))->>'state'),'committed','interrupted response can reconcile without draft storage');
select throws_ok($$select save_trip_expense_editor(gen_random_uuid(),pg_temp.id('private-a'),1,pg_temp.id('trip'),'private',false,pg_temp.payload('personal',array[pg_temp.id('u2')],array[10000::bigint],array[10000::bigint],10000),array[pg_temp.id('u2')])$$,'P0001','version_conflict','stale save does not overwrite');
insert into te values('promoted',(save_trip_expense_editor(gen_random_uuid(),pg_temp.id('private-a'),2,pg_temp.id('trip'),'shared',false,pg_temp.payload('space',array[pg_temp.id('u2'),pg_temp.id('u3')],array[10000::bigint,0],array[5000::bigint,5000],10000,'Public successor'),array[pg_temp.id('u2'),pg_temp.id('u3')])->>'expense_id')::uuid);
select is((select status from expenses where id=pg_temp.id('private-a')),'voided','private predecessor superseded, not overwritten');
select is((select corrects_expense_id from expenses where id=pg_temp.id('promoted')),pg_temp.id('private-a'),'immutable original correction lineage');
select is((select count(*)from personal_account_entries),0::bigint,'audience change creates no invented deduction');
select pg_temp.claim(3);
select is((select description from expenses where id=pg_temp.id('promoted')),'Public successor','B reads only successor public content');
select is((select count(*)from expenses where id=pg_temp.id('private-a')),0::bigint,'private predecessor never exposed after promotion');
select is((select count(*)from expense_editor_settings where expense_id=pg_temp.id('private-a')),0::bigint,'private predecessor items never exposed');
select is((select count(*)from financial_events where expense_id=pg_temp.id('private-a')),0::bigint,'private correction event stays private');
select pg_temp.claim(2);
select throws_ok($$select save_trip_expense_editor(gen_random_uuid(),pg_temp.id('promoted'),1,pg_temp.id('trip'),'private',true,pg_temp.payload('personal',array[pg_temp.id('u2')],array[10000::bigint],array[10000::bigint],10000),array[pg_temp.id('u2')])$$,'P0001','audience_transition_has_dependencies','cannot hide another consumer obligation');
insert into te values('zero-other',(create_trip_expense_editor(gen_random_uuid(),pg_temp.id('trip'),pg_temp.payload('space',array[pg_temp.id('u2'),pg_temp.id('u3')],array[10000::bigint,0],array[10000::bigint,0],10000),array[pg_temp.id('u2'),pg_temp.id('u3')])->>'expense_id')::uuid);
select is((get_trip_expense_editor(pg_temp.id('zero-other'))->>'audience'),'shared','explicit zero-share other consumer remains Shared');
select throws_ok($$select save_trip_expense_editor(gen_random_uuid(),pg_temp.id('zero-other'),1,pg_temp.id('trip'),'private',false,pg_temp.payload('personal',array[pg_temp.id('u2')],array[10000::bigint],array[10000::bigint],10000),array[pg_temp.id('u2')])$$,'P0001','private_confirmation_required','Shared to private needs explicit confirmation');
insert into te values('demoted',(save_trip_expense_editor(gen_random_uuid(),pg_temp.id('zero-other'),1,pg_temp.id('trip'),'private',true,pg_temp.payload('personal',array[pg_temp.id('u2')],array[10000::bigint],array[10000::bigint],10000,'Private successor note'),array[pg_temp.id('u2')])->>'expense_id')::uuid);
select is((get_trip_expense_editor(pg_temp.id('demoted'))->>'audience'),'private','eligible explicit conversion is private');
select pg_temp.claim(3);
select is((select count(*)from expenses where id=pg_temp.id('demoted')),0::bigint,'Shared predecessor grants no private successor access');
select is((select status from expenses where id=pg_temp.id('zero-other')),'voided','original Shared audit retained');
select is((reconcile_personal_money_operation(pg_temp.id('save-command'))->>'state'),'not_posted','original reconciliation fence is owner scoped');
select pg_temp.claim(2);
insert into te values('account',public.create_personal_account(gen_random_uuid(),'Private source','cash','MYR',null,null,false));
select lives_ok($$select save_trip_expense_editor(gen_random_uuid(),pg_temp.id('demoted'),1,pg_temp.id('trip'),'private',false,pg_temp.payload('personal',array[pg_temp.id('u2')],array[10000::bigint],array[10000::bigint],10000,'Private successor note'),array[pg_temp.id('u2')],'exact','[]',jsonb_build_object('intent_id',null,'version',null,'account_id',pg_temp.id('account')))$$,'account choice defers through original command in same Save');
select is((select version from expenses where id=pg_temp.id('demoted')),2,'account/settings-only Save also advances expected version');
select is((select count(*)from personal_account_entries),0::bigint,'account choice does not confirm or post a deduction');
insert into te select 'pending',id from personal_funding_intents where expense_id=pg_temp.id('demoted')and status='pending';
select lives_ok($$select save_trip_expense_editor(gen_random_uuid(),pg_temp.id('demoted'),2,pg_temp.id('trip'),'private',false,pg_temp.payload('personal',array[pg_temp.id('u2')],array[10000::bigint],array[10000::bigint],10000,'Private successor note'),array[pg_temp.id('u2')],'exact','[]',jsonb_build_object('intent_id',pg_temp.id('pending'),'version',1,'account_id',null))$$,'pending candidate changes use original cancellation/defer, no cash');
select is((select status from personal_funding_intents where id=pg_temp.id('pending')),'cancelled','old candidate history retained');
select is((select count(*)from personal_funding_intents where expense_id=pg_temp.id('demoted')and status='pending'),1::bigint,'only one active pending candidate');
insert into te values('posted',(create_trip_expense_editor(gen_random_uuid(),pg_temp.id('trip'),pg_temp.payload('personal',array[pg_temp.id('u2')],array[3000::bigint],array[3000::bigint],3000),array[pg_temp.id('u2')],null,pg_temp.id('account'))->>'expense_id')::uuid);
select is((select count(*)from personal_account_entries),1::bigint,'original funded creation posts exactly once');
insert into te values('posted-promoted',(save_trip_expense_editor(gen_random_uuid(),pg_temp.id('posted'),1,pg_temp.id('trip'),'shared',false,pg_temp.payload('space',array[pg_temp.id('u2'),pg_temp.id('u3')],array[3000::bigint,0],array[1500::bigint,1500],3000),array[pg_temp.id('u2'),pg_temp.id('u3')])->>'expense_id')::uuid);
select is((select count(*)from personal_account_entries),1::bigint,'promotion never reposts posted cash');
select is((select expense_id from personal_funding_intents where status='posted'),pg_temp.id('posted'),'posted original association immutable');
select is(jsonb_array_length(get_trip_expense_editor(pg_temp.id('posted-promoted'))->'funding'),1,'owner sees original funding through authoritative lineage');
select pg_temp.claim(3);
select is(jsonb_array_length(get_trip_expense_editor(pg_temp.id('posted-promoted'))->'funding'),0,'other member cannot see original private account identity');
select pg_temp.claim(2);
select throws_ok($$select save_trip_expense_editor(gen_random_uuid(),pg_temp.id('posted-promoted'),1,pg_temp.id('trip'),'shared',false,pg_temp.payload('space',array[pg_temp.id('u2'),pg_temp.id('u3')],array[3000::bigint,0],array[1500::bigint,1500],3000),array[pg_temp.id('u2'),pg_temp.id('u3')],'exact','[]',jsonb_build_object('intent_id',null,'version',null,'account_id',pg_temp.id('account')))$$,'P0001','posted_funding_immutable','posted source cannot be silently replaced');
select is((select version from expenses where id=pg_temp.id('posted-promoted')),1,'failed source change rolls back complete draft');
select throws_ok($$select create_trip_expense_editor(gen_random_uuid(),pg_temp.id('trip'),pg_temp.payload('space',array[pg_temp.id('u2'),pg_temp.id('u3')],array[10001::bigint,0],array[5000::bigint,5001],10001),array[pg_temp.id('u2'),pg_temp.id('u3')],null,null,'equal')$$,'P0001','split_metadata_mismatch','metadata cannot claim Equal with different canonical remainder order');
reset role;
select is(has_function_privilege('anon','public.get_trip_expense_editor(uuid)','EXECUTE'),false,'anonymous editor denied');
select is(has_table_privilege('authenticated','public.expense_editor_settings','UPDATE'),false,'no direct split metadata writes');
select is(has_function_privilege('authenticated','private.link_personal_trip_expense(uuid,uuid,uuid)','EXECUTE'),false,'association helper private');
select * from finish();
rollback;
